import {alphabet,fields,steps,flightKey,validFlight,fieldError,atisReady,phraseParts} from './radio-model.js';
const $=id=>document.getElementById(id);
const make=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!=null)n.textContent=text;return n;};
let flight;try{flight=JSON.parse(sessionStorage.getItem('vatsim-companion-flight-v1'));}catch{}
if(!validFlight(flight)){$('missing-flight').hidden=false;}else{start();}
function start(){
 $('radio-app').hidden=false;
 const key=flightKey(flight);let saved;try{saved=JSON.parse(sessionStorage.getItem('vatsim-radio-v1'));}catch{}
 let values=saved?.flightKey===key&&saved.values&&typeof saved.values==='object'?saved.values:{};
 values=Object.fromEntries(Object.entries(values).filter(([k,v])=>fields[k]&&typeof v==='string').map(([k,v])=>[k,v.slice(0,100)]));
 let index=saved?.flightKey===key&&Number.isInteger(saved.index)?Math.max(0,Math.min(saved.index,steps.length-1)):0;
 if(!atisReady(values))index=0;
 const airports={departure:flight.departureAirport,arrival:flight.arrivalAirport};
 const callsign=flight.airline+flight.flightNumber;
 $('flight-title').textContent=callsign+' · Radio script';$('route').textContent=flight.departure+' → '+flight.arrival;
 function persist(){try{sessionStorage.setItem('vatsim-radio-v1',JSON.stringify({flightKey:key,index,values}));$('save-status').textContent='Entries saved in this tab.';}catch{$('save-status').textContent='Unable to save entries. Keep this page open.';}}
 function resolved(){const valid=Object.fromEntries(Object.entries(values).filter(([k,v])=>!fieldError(k,v)));return {...valid,callsign,stand:flight.gate,aircraft:flight.aircraftLabel||(flight.aircraft==='OTHER'?flight.customAircraft:flight.aircraft),destination:airports.arrival?.name||flight.arrival};}
 function cards(){const fragment=document.createDocumentFragment();for(const c of steps[index].cards){const card=make('article','card '+c.role),head=make('div','card-head');head.append(make('strong','',c.role==='atc'?'ATC example':c.role==='pilot'?'You say':'Remember'),make('span','',c.title));const p=make('p');let missing=false;for(const part of phraseParts(c.text,resolved())){if(part.key){p.append(make('span',part.missing?'missing':'filled',part.text));missing ||=!!part.missing;}else p.append(document.createTextNode(part.text));}card.append(head,p);if(missing)card.append(make('small','pending','Fill the highlighted details from your ATIS or ATC instruction before using this line.'));fragment.append(card);}$('cards').replaceChildren(fragment);}
 function navigate(next){if(next>0&&!atisReady(values)){index=0;render();$('stage-error').textContent='Enter the ATIS information and a valid QNH before continuing.';document.getElementById(values.info?'qnh':'info').focus();return;}index=next;persist();render();$('stage-title').focus();}
 function render(){const step=steps[index];$('phase').textContent=step.phase.toUpperCase()+' / '+step.name.toUpperCase();$('stage-title').textContent=step.title;$('description').textContent=step.description;$('stage-error').textContent='';$('steps').replaceChildren();steps.forEach((s,i)=>{const b=make('button');b.type='button';if(i===index)b.setAttribute('aria-current','step');const content=make('span');content.append(make('strong','',s.name),make('small','',s.phase));b.append(make('span','step-number',String(i+1).padStart(2,'0')),content);b.addEventListener('click',()=>navigate(i));$('steps').append(b);});$('fields').replaceChildren();
 for(const k of step.fields){const f=fields[k],wrap=make('div'),label=make('label','',f.label);label.htmlFor=k;let input;if(f.type==='info'){input=make('select');input.append(new Option('Select information…',''));alphabet.forEach((word,i)=>input.append(new Option(String.fromCharCode(65+i)+' — '+word,word)));}else{input=make('input');input.type='text';input.placeholder=f.placeholder||'';input.maxLength=f.type==='qnh'||f.type==='squawk'?4:80;if(['qnh','squawk'].includes(f.type))input.inputMode='numeric';if(f.type==='runway'){const datalist=make('datalist');datalist.id=k+'-suggestions';const ends=new Set((airports[f.airport]?.runways||[]).flatMap(r=>r.ends.split(' / ')));ends.forEach(end=>datalist.append(new Option(end,end)));input.setAttribute('list',datalist.id);wrap.append(datalist);}}
 input.id=k;input.value=values[k]||'';input.autocomplete='off';input.setAttribute('aria-describedby',k+'-error');const error=make('p','field-error',fieldError(k,input.value));error.id=k+'-error';input.addEventListener('input',()=>{let value=input.value;if(['runway','squawk'].includes(f.type))value=value.toUpperCase();input.value=value;values[k]=value.trim();const message=fieldError(k,values[k]);error.textContent=message;input.setAttribute('aria-invalid',String(!!message));$('stage-error').textContent='';persist();cards();});wrap.append(label,input,error);$('fields').append(wrap);
 }cards();$('previous').disabled=index===0;$('next').textContent=index===steps.length-1?'Finish flight ✓':steps[index+1].name+' →';$('count').textContent=`${index+1} / ${steps.length}`;}
 $('previous').addEventListener('click',()=>{if(index>0)navigate(index-1);});$('next').addEventListener('click',()=>{if(index<steps.length-1)navigate(index+1);else{persist();$('save-status').textContent='Flight complete. Your script and notes remain available in this tab.';}});
 render();
 for(const kind of ['departure','arrival']){fetch('/api/airports/'+flight[kind],{signal:AbortSignal.timeout(12000)}).then(r=>{if(!r.ok)throw new Error();return r.json();}).then(body=>{airports[kind]=body.data;cards();for(const k of ['departureRunway','arrivalRunway']){const list=document.getElementById(k+'-suggestions');if(list&&fields[k].airport===kind){list.replaceChildren();new Set(body.data.runways.flatMap(r=>r.ends.split(' / '))).forEach(end=>list.append(new Option(end,end)));}}}).catch(()=>{if(!airports[kind])$('save-status').textContent='Airport details unavailable; using ICAO codes. You can still enter assigned runways.';});}
}
